-- ThothMemory Mini schema 1. Each statement ends with a semicolon at end of line.
-- Identifiers are ASCII binary so UUID/revision comparison and ordering match
-- PostgreSQL. Text is utf8mb4 binary; search_text is NFC-lowercased by the
-- application because MariaDB has no Unicode normalization function.
CREATE TABLE principals(id VARCHAR(200) NOT NULL PRIMARY KEY, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE projects(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, name VARCHAR(200) NOT NULL CHECK(CHAR_LENGTH(name) BETWEEN 1 AND 200), repository VARCHAR(1000) NOT NULL CHECK(CHAR_LENGTH(repository) BETWEEN 1 AND 1000), repository_key BINARY(32) AS (UNHEX(SHA2(repository,256))) STORED, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), event_count BIGINT NOT NULL DEFAULT 0 CHECK(event_count>=0), event_budget BIGINT NOT NULL DEFAULT 100000 CHECK(event_budget BETWEEN 100 AND 10000000), UNIQUE KEY projects_repository(repository_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE agents(id VARCHAR(100) NOT NULL PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE sessions(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, agent_id VARCHAR(100) NOT NULL, principal_id VARCHAR(200) NOT NULL, branch VARCHAR(500) NOT NULL, git_revision VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, started_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), finished_at DATETIME(6) NULL, revision INT NOT NULL DEFAULT 1, UNIQUE KEY sessions_project_id(project_id,id), KEY sessions_project_time(project_id,started_at), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(agent_id) REFERENCES agents(id), FOREIGN KEY(principal_id) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE tasks(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, title VARCHAR(500) NOT NULL CHECK(CHAR_LENGTH(title) BETWEEN 1 AND 500), state VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'planned' CHECK(state IN ('planned','active','blocked','implemented','committed','tested','verified','released')), revision INT NOT NULL DEFAULT 1 CHECK(revision>0), git_revision VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', claimed_by VARCHAR(200) NULL, claim_expires_at DATETIME(6) NULL, updated_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), search_text TEXT NOT NULL, UNIQUE KEY tasks_project_id(project_id,id), KEY tasks_project_state(project_id,state,updated_at), KEY tasks_project_time(project_id,updated_at), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(claimed_by) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE task_dependencies(project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, task_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, depends_on CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, PRIMARY KEY(project_id,task_id,depends_on), KEY task_dependencies_reverse(project_id,depends_on), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,depends_on) REFERENCES tasks(project_id,id), CHECK(task_id<>depends_on)) ENGINE=InnoDB;
CREATE TABLE evidence(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, task_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, source_kind VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(source_kind IN ('git_commit','pull_request','build','test','ci','log','human','inference','release')), locator VARCHAR(2000) NOT NULL CHECK(CHAR_LENGTH(locator) BETWEEN 1 AND 2000), git_revision VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, artifact_digest VARCHAR(200) NOT NULL DEFAULT '', outcome VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(outcome IN ('pass','fail','unknown')), summary TEXT NOT NULL CHECK(CHAR_LENGTH(summary) BETWEEN 1 AND 8000), reported_by VARCHAR(200) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), search_text MEDIUMTEXT NOT NULL, UNIQUE KEY evidence_project_id(project_id,id), KEY evidence_task_revision(project_id,task_id,git_revision), KEY evidence_project_time(project_id,created_at), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(reported_by) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE attestations(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, evidence_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, principal_id VARCHAR(200) NOT NULL, statement TEXT NOT NULL CHECK(CHAR_LENGTH(statement) BETWEEN 1 AND 8000), created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), UNIQUE KEY attestations_evidence(evidence_id), KEY attestations_project(project_id), FOREIGN KEY(project_id,evidence_id) REFERENCES evidence(project_id,id), FOREIGN KEY(principal_id) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE events(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, task_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, session_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, kind VARCHAR(100) NOT NULL, body TEXT NOT NULL CHECK(CHAR_LENGTH(body) BETWEEN 1 AND 8000), principal_id VARCHAR(200) NOT NULL, agent_id VARCHAR(100) NOT NULL DEFAULT '', git_revision VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), details LONGTEXT NOT NULL CHECK(JSON_VALID(details)), search_text MEDIUMTEXT NOT NULL, KEY events_project_time(project_id,created_at,id), KEY events_task_time(project_id,task_id,created_at), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id), FOREIGN KEY(principal_id) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE records(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, task_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, session_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, kind VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(kind IN ('decision','issue','observation','handoff','idea','note')), title VARCHAR(500) NOT NULL CHECK(CHAR_LENGTH(title) BETWEEN 1 AND 500), body TEXT NOT NULL CHECK(CHAR_LENGTH(body) BETWEEN 1 AND 8000), git_revision VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', principal_id VARCHAR(200) NOT NULL, agent_id VARCHAR(100) NOT NULL DEFAULT '', evidence_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, supersedes CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), search_text MEDIUMTEXT NOT NULL, UNIQUE KEY records_project_id(project_id,id), UNIQUE KEY records_supersedes(supersedes), KEY records_project_time(project_id,created_at,id), KEY records_project_kind(project_id,kind,created_at), KEY records_session(project_id,session_id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id), FOREIGN KEY(project_id,evidence_id) REFERENCES evidence(project_id,id), FOREIGN KEY(project_id,supersedes) REFERENCES records(project_id,id), FOREIGN KEY(principal_id) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE operations(project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, operation_id VARCHAR(100) NOT NULL CHECK(CHAR_LENGTH(operation_id) BETWEEN 8 AND 100), principal_id VARCHAR(200) NOT NULL, payload_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, response LONGTEXT NOT NULL CHECK(JSON_VALID(response)), created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), PRIMARY KEY(project_id,principal_id,operation_id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(principal_id) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE imports(id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, project_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, export_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, source_edition VARCHAR(10) NOT NULL CHECK(source_edition IN ('full','mini','ultralite')), source_version VARCHAR(50) NOT NULL, format_version INT NOT NULL, checksum CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, counts LONGTEXT NOT NULL CHECK(JSON_VALID(counts)), principal_id VARCHAR(200) NOT NULL, imported_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)), UNIQUE KEY imports_checksum(project_id,checksum), KEY imports_project_time(project_id,imported_at), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(principal_id) REFERENCES principals(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TRIGGER immutable_events_update BEFORE UPDATE ON events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_events_delete BEFORE DELETE ON events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_records_update BEFORE UPDATE ON records FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_records_delete BEFORE DELETE ON records FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_evidence_update BEFORE UPDATE ON evidence FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_evidence_delete BEFORE DELETE ON evidence FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_attestations_update BEFORE UPDATE ON attestations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_attestations_delete BEFORE DELETE ON attestations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_operations_update BEFORE UPDATE ON operations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_operations_delete BEFORE DELETE ON operations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_imports_update BEFORE UPDATE ON imports FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
CREATE TRIGGER immutable_imports_delete BEFORE DELETE ON imports FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='history is append-only';
